 auto d=std::make_shared<ParticleEmitterDefinition>();d->renderMode=ParticleRenderMode::Ribbon;d->space=ParticleSpace::World;d->trailMinDistance=.1f;d->trailBreakDistance=5;d->trailLifetime=10;d->trailMaxPoints=16;
